export const lanes=coordinates.map(list=>{let total=0;const samples=list.map(([x,y],i)=>{if(i)total+=Math.hypot(x-list[i-1][0],y-list[i-1][1]);return{x,y,s:total}});return{samples,length:total}});
export function lanePoint(index,progress){const {samples,length}=lanes[index],s=((progress%1)+1)%1*length;const at=d=>{d=(d%length+length)%length;let lo=0,hi=samples.length-1;while(hi-lo>1){const m=(hi+lo)>>1;if(samples[m].s>d)hi=m;else lo=m}const p=samples[lo],q=samples[hi],t=(d-p.s)/(q.s-p.s);return{x:p.x+(q.x-p.x)*t,y:p.y+(q.y-p.y)*t}};const p=at(s),a=at(s-12),b=at(s+12);return{...p,a:Math.atan2(b.y-a.y,b.x-a.x),z:0,curvature:0,slope:0}}
export const length=lanes[0].length,path=lanes[0].samples.map(p=>({...lanePoint(0,p.s/length),s:p.s})),knots=coordinates[0],curves=[];
export function point(s,lane=0){const p=lanePoint(0,s/length);return{...p,x:p.x-Math.sin(p.a)*lane,y:p.y+Math.cos(p.a)*lane}}
export const forwardGap=(a,b)=>(b-a+length)%length;
export function project(p){return{x:p.x*VIEW_X,y:p.y,z:0,a:Math.atan2(Math.sin(p.a??0),VIEW_X*Math.cos(p.a??0)),bodyA:p.a??0}}
